const saveText = aras.getResource('../Modules/aras.innovator.ExtendedClassification/', 'classEditor.tree.toolbar.save');
const cancelText = aras.getResource('../Modules/aras.innovator.ExtendedClassification/', 'classEditor.tree.toolbar.cancel');
const saveButton = document.body.querySelector('input[name=\'saveButton\']');
saveButton.value = saveText;
const cancelButton = document.body.querySelector('input[name=\'cancelButton\']');
cancelButton.value = cancelText;
cancelButton.classList.add('btn_cancel');
cancelButton.classList.add('aras-btn');
saveButton.addEventListener('click', function() {
	window.parent.dialogArguments.buttonClickHandler('save');
});
cancelButton.addEventListener('click', function() {
	window.parent.dialogArguments.buttonClickHandler('cancel');
});
